#include <iostream>
#include <sstream>

#include <string>
#include <ios>

void probar(const std::string& texto, bool grave) {
    std::istringstream entrada{texto};
    if (grave) entrada.setstate(std::ios::badbit);
    int valor = 0;
    while (entrada >> valor) {
        std::cout << "Dato: " << valor << "\n";
    }
    if (entrada.bad()) {
        std::cout << "Fallo del flujo";
    } else if (entrada.eof()) {
        std::cout << "Fin";
    } else {
        std::cout << "Formato invalido";
    }
    std::cout << "\n";
}

int main() {
    probar("2 7 x 4", false);
    probar("3 8", false);
    probar("", false);
    probar("5 ", false);
    probar("9z", false);
    probar("x 6", false);
    probar("2 -", false);
    probar("3", true);
    return 0;
}
